//! olvin-editor with every element, for working on the editor itself.
//! Real installs are generated by olvin-hub with the elements the user picked.

fn main() {
    olvin_editor::run(vec![
        Box::new(olvin_editor_console::ConsolePlugin),
        Box::new(olvin_editor_animator::AnimatorPlugin),
        Box::new(olvin_editor_csg::CsgPlugin),
    ]);
}
